const limit:I64=comptime 30;
fn Prime(n:view I64)->Bool{
    if n<2{
        return false;
    }
    var d=2;
    while d<=n/d{
        if n%d==0{
            return false;
        }
        d+=1;
    }
    return true;
}
fn Main(){
    var primes:Array<I64>=[];
    for n in 0..=limit{
        if not Prime(n){
            continue;
        }
        Push(edit primes,n);
    }
    AssertEq(Len(primes),10);
    AssertEq(primes[0],2);
    AssertEq(primes[9],29);
    var sum=0;
    for p in primes{
        sum+=p;
    }
    Print(primes);
    Print(sum);
}

acceptance_programs.F5-P02:
const limit:I64=comptime 30;
fn Main(){
    var composite:Array<Bool>=[];
    for i in 0..=limit{
        Push(edit composite,false);
    }
    composite[0]=true;
    composite[1]=true;
    var p=2;
    while p<=limit/p{
        if composite[p]{
            p+=1;
            continue;
        }
        var multiple=p*p;
        while multiple<=limit{
            composite[multiple]=true;
            multiple+=p;
        }
        p+=1;
    }
    var primes:Array<I64>=[];
    for n in 2..=limit{
        if not composite[n]{
            Push(edit primes,n);
        }
    }
    AssertEq(Len(primes),10);
    AssertEq(composite[25],true);
    Print(primes);
}

acceptance_programs.F5-P03:
const start:I64=comptime 27;
fn Step(n:view I64)->I64{
    if n%2==0{
        return n/2;
    }
    return 3*n+1;
}
fn Main(){
    var n=start;
    var steps=0;
    var peak=n;
    var odd=0;
    while true{
        if n==1{
            break;
        }
        if n%2!=0{
            odd+=1;
        }
        n=Step(n);
        steps+=1;
        if n>peak{
            peak=n;
        }
    }
    AssertEq(n,1);
    AssertEq(odd,41);
    Print(steps);
    Print(peak);
    Print(odd);
}

