const size:I64=comptime 3;
fn Identity()->Array<Array<I64>>{
    var matrix:Array<Array<I64>>=[];
    for rowIndex in 0..<size{
        var row:Array<I64>=[];
        for column in 0..<size{
            let cell=if rowIndex==column then{
                value:1;
            }else{
                value:0;
            };
            Push(edit row,cell);
        }
        Push(edit matrix,move row);
    }
    return move matrix;
}
fn Main(){
    let matrix=Identity();
    var copy=matrix;
    copy[0][0]=9;
    AssertEq(matrix[0][0],1);
    AssertEq(copy[0][0],9);
    var trace=0;
    for i in 0..<size{
        trace+=matrix[i][i];
    }
    AssertEq(trace,size);
    Print(matrix);
    Print(trace);
}

