const buckets:I64=comptime 5;
fn Main(){
    let values=[0,1,1,4,2,4,4,3,0,-1,5];
    var counts:Array<I64>=[];
    for bucket in 0..<buckets{
        Push(edit counts,0);
    }
    var rejected=0;
    for value in values{
        if value<0 or value>=buckets{
            rejected+=1;
            continue;
        }
        counts[value]+=1;
    }
    var total=0;
    var maximum=0;
    for count in counts{
        total+=count;
        if count>maximum{
            maximum=count;
        }
    }
    AssertEq(total+rejected,Len(values));
    AssertEq(counts,[2,2,1,1,3]);
    AssertEq(maximum,3);
    Print(counts);
    Print(total);
    Print(rejected);
    Print(maximum);
}

